<section class="panel gap-top" id="kendala"><div class="panel-head"><h2>Kendala & tindak lanjut</h2><span class="badge {{ $order->issues->where('status','OPEN')->count() ? 'warn' : '' }}">{{ $order->issues->where('status', 'OPEN')->count() }} aktif</span></div><div class="panel-body">
