@foreach($issue->notes as $note)<div class="issue-note"><div class="small muted">{{ $note->actor->name }} · {{ $note->created_at->timezone('Asia/Jakarta')->format('d M Y H:i') }} WIB</div><p class="preserve-lines">{{ $note->note }}</p></div>@endforeach
