@if(! $order->terminal())<details class="gap-top"><summary>Tambah catatan tindak lanjut</summary><form method="POST" action="{{ route('issues.notes', $issue) }}" data-loading="Menyimpan catatan…">@csrf<input type="hidden" name="revision" value="{{ $order->revision }}"><label for="issue-note-{{ $issue->getKey() }}">Catatan / detail terbaru</label><textarea id="issue-note-{{ $issue->getKey() }}" name="note" required maxlength="2000" placeholder="Tuliskan hasil koordinasi atau perkembangan kendala…"></textarea><button type="submit" class="button secondary gap-top">Tambah catatan</button></form></details>@endif
<details class="gap-top"><summary>Selesaikan kendala</summary><form method="POST" action="{{ route('issues.resolve', $issue) }}" data-loading="Menyimpan penyelesaian…">@csrf @method('PATCH')<input type="hidden" name="revision" value="{{ $order->revision }}"><label for="resolution-{{ $issue->getKey() }}">Hasil penyelesaian</label><textarea id="resolution-{{ $issue->getKey() }}" name="resolution" required maxlength="2000" placeholder="Jelaskan bagaimana kendala diselesaikan…"></textarea><button type="submit" class="button secondary gap-top">Tandai selesai</button></form></details>
