@can('update', $order)@if(! $order->terminal())<details class="gap-top"><summary>Catat kendala baru</summary><form method="POST" action="{{ route('work-orders.issues', $order) }}" data-loading="Menyimpan kendala…">@csrf<input type="hidden" name="revision" value="{{ $order->revision }}"><div class="grid two compact-grid"><div><label for="issue-category">Kategori kendala</label><select id="issue-category" name="category">@foreach($issueLabels as $code=>$label)<option value="{{ $code }}">{{ $label }}</option>@endforeach</select></div><div><label for="issue-pic">PIC tindak lanjut</label><input id="issue-pic" name="pic" value="{{ old('pic', auth()->user()->name) }}" required maxlength="120"></div></div><label for="issue-description">Detail kendala</label><textarea id="issue-description" name="description" required maxlength="2000" placeholder="Apa kendalanya dan langkah tindak lanjut yang diperlukan?">{{ old('description') }}</textarea><label for="issue-eta">Target penyelesaian <span class="muted">· opsional</span></label><input id="issue-eta" name="eta" type="date" value="{{ old('eta') }}"><button type="submit" class="button secondary gap-top">Simpan kendala</button></form></details>@endif @endcan
